-- Rentals Phase 48: reusable inspection templates and scheduled mobile execution.
begin;
create table public.rental_inspection_templates(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete restrict,name text not null check(length(btrim(name))>0),inspection_type text not null check(inspection_type in('incoming','routine','outgoing','maintenance_follow_up')),status text not null default 'active' check(status in('active','archived')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organisation_id,name,inspection_type));
create table public.rental_inspection_template_items(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.rental_inspection_templates(id) on delete restrict,item_key text not null,item_label text not null,sort_order integer not null default 0,required boolean not null default true,unique(template_id,item_key));
create table public.rental_inspection_schedules(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete restrict,property_id uuid not null references public.rental_properties(id) on delete restrict,unit_id uuid references public.rental_units(id) on delete restrict,tenancy_id uuid references public.rental_tenancies(id) on delete restrict,template_id uuid not null references public.rental_inspection_templates(id) on delete restrict,scheduled_for timestamptz not null,assigned_to uuid references auth.users(id),status text not null default 'scheduled' check(status in('scheduled','started','completed','cancelled')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(unit_id is not null or tenancy_id is not null));
create index rental_inspection_schedules_queue_idx on public.rental_inspection_schedules(organisation_id,status,scheduled_for);alter table public.rental_inspection_templates enable row level security;alter table public.rental_inspection_template_items enable row level security;alter table public.rental_inspection_schedules enable row level security;revoke all on public.rental_inspection_templates,public.rental_inspection_template_items,public.rental_inspection_schedules from anon,authenticated;grant select on public.rental_inspection_templates,public.rental_inspection_template_items,public.rental_inspection_schedules to authenticated;
create policy rental_inspection_templates_read on public.rental_inspection_templates for select to authenticated using(exists(select 1 from public.rental_properties p where p.organisation_id=organisation_id and public.rental_branch_access(p.organisation_id,p.branch_id)));create policy rental_inspection_template_items_read on public.rental_inspection_template_items for select to authenticated using(exists(select 1 from public.rental_inspection_templates t join public.rental_properties p on p.organisation_id=t.organisation_id where t.id=template_id and public.rental_branch_access(p.organisation_id,p.branch_id)));create policy rental_inspection_schedules_read on public.rental_inspection_schedules for select to authenticated using(exists(select 1 from public.rental_properties p where p.id=property_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
alter table public.rental_field_inspections add column template_id uuid references public.rental_inspection_templates(id) on delete restrict,add column schedule_id uuid unique references public.rental_inspection_schedules(id) on delete restrict;
create or replace function public.rental_create_inspection_template(p_organisation uuid,p_name text,p_type text,p_items jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare tid uuid;x jsonb;i integer:=0;begin if auth.uid() is null or p_type not in('incoming','routine','outgoing','maintenance_follow_up') or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Name, type and at least one item are required';end if;if not public.rental_financial_manager_authorized(p_organisation) then raise exception 'Manager authorization is required';end if;insert into public.rental_inspection_templates(organisation_id,name,inspection_type,created_by)values(p_organisation,btrim(p_name),p_type,auth.uid())returning id into tid;for x in select value from jsonb_array_elements(p_items) loop i:=i+1;if length(coalesce(x->>'key',''))>0 and length(coalesce(x->>'label',''))>0 then insert into public.rental_inspection_template_items(template_id,item_key,item_label,sort_order,required)values(tid,x->>'key',x->>'label',i,coalesce((x->>'required')::boolean,true));end if;end loop;return jsonb_build_object('template_id',tid);end$$;
create or replace function public.rental_schedule_inspection(p_tenancy uuid,p_template uuid,p_scheduled_for timestamptz,p_assigned_to uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype;tpl public.rental_inspection_templates%rowtype;sid uuid;begin if auth.uid() is null or p_scheduled_for is null then raise exception 'Schedule time required';end if;select * into t from public.rental_tenancies where id=p_tenancy for update;if not found or not exists(select 1 from public.rental_properties p where p.id=t.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;select * into tpl from public.rental_inspection_templates where id=p_template and status='active';if not found or tpl.organisation_id<>t.organisation_id then raise exception 'Active template required';end if;insert into public.rental_inspection_schedules(organisation_id,property_id,unit_id,tenancy_id,template_id,scheduled_for,assigned_to,created_by)values(t.organisation_id,t.property_id,t.unit_id,t.id,tpl.id,p_scheduled_for,p_assigned_to,auth.uid())returning id into sid;return jsonb_build_object('schedule_id',sid,'status','scheduled');end$$;
create or replace function public.rental_start_scheduled_inspection(p_schedule uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s public.rental_inspection_schedules%rowtype;iid uuid;x public.rental_inspection_template_items%rowtype;begin select * into s from public.rental_inspection_schedules where id=p_schedule for update;if not found or not exists(select 1 from public.rental_properties p where p.id=s.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;if s.status<>'scheduled' then raise exception 'Inspection is not available to start';end if;insert into public.rental_field_inspections(organisation_id,property_id,unit_id,tenancy_id,inspection_type,template_id,schedule_id,started_by)select s.organisation_id,s.property_id,s.unit_id,s.tenancy_id,t.inspection_type,t.id,s.id,auth.uid() from public.rental_inspection_templates t where t.id=s.template_id returning id into iid;for x in select * from public.rental_inspection_template_items where template_id=s.template_id order by sort_order,id loop insert into public.rental_field_inspection_items(inspection_id,item_key,item_label,updated_by)values(iid,x.item_key,x.item_label,auth.uid());end loop;update public.rental_inspection_schedules set status='started' where id=s.id;return jsonb_build_object('inspection_id',iid,'schedule_id',s.id,'status','in_progress');end$$;
revoke execute on function public.rental_create_inspection_template(uuid,text,text,jsonb),public.rental_schedule_inspection(uuid,uuid,timestamptz,uuid),public.rental_start_scheduled_inspection(uuid) from public,anon;grant execute on function public.rental_create_inspection_template(uuid,text,text,jsonb),public.rental_schedule_inspection(uuid,uuid,timestamptz,uuid),public.rental_start_scheduled_inspection(uuid) to authenticated;commit;
